function pairWithSum(sorted, target) {
  let left = 0
  let right = sorted.length - 1
  while (left < right) {
    const sum = sorted[left] + sorted[right]
    if (sum === target) return [sorted[left], sorted[right]]
    if (sum < target) left++
    else right--
  }
  return null
}
