def pair_with_sum(sorted_nums, target):
    left = 0
    right = len(sorted_nums) - 1
    while left < right:
        total = sorted_nums[left] + sorted_nums[right]
        if total == target:
            return [sorted_nums[left], sorted_nums[right]]
        if total < target:
            left += 1
        else:
            right -= 1
    return None

