function longestUnique(text) {
  const lastSeen = new Map()
  let start = 0
  let best = 0
  for (let end = 0; end < text.length; end++) {
    const ch = text[end]
    const prev = lastSeen.get(ch)
    if (prev !== undefined && prev >= start) start = prev + 1
    lastSeen.set(ch, end)
    best = Math.max(best, end - start + 1)
  }
  return best
}
console.log(longestUnique('abcabcbb'), longestUnique('pwwkew'), longestUnique('aaaa'))

