def longest_unique(text):
    last_seen = {}
    start = 0
    best = 0
    for end, ch in enumerate(text):
        if last_seen.get(ch, -1) >= start:
            start = last_seen[ch] + 1
        last_seen[ch] = end
        best = max(best, end - start + 1)
    return best

print(longest_unique('abcabcbb'), longest_unique('pwwkew'), longest_unique('aaaa'))
